-- ═══════════════════════════════════════════════════════════════════
-- ล้างข้อมูลสัญญาและธุรกรรมเดิม แล้วใส่ข้อมูลตัวอย่างชุดใหม่
-- สร้างเมื่อ 2026-08-27 · ทะเบียนทั้งหมดไม่ถูกแตะ
--
--   เก็บไว้  ผู้ขาย/ธนาคาร · บริษัทในเครือ · ผังบัญชี · ดอกเบี้ย
--            Curtailment · ประเภทวงเงิน · ผู้ใช้ · กลุ่มสิทธิ์
--   ล้าง     สัญญาหลัก · วงเงิน · ธุรกรรมทุกเมนู · ใบสำคัญบัญชี
--            ตัดชำระ · ใบแจ้งยอด · ตารางผ่อน · ทะเบียนรถ
-- ═══════════════════════════════════════════════════════════════════

BEGIN;

-- ── 1 · ล้างข้อมูลเดิม ────────────────────────────────────────────
--
-- ใช้ TRUNCATE ... CASCADE ทีเดียวทั้งชุด แทนการไล่ลบทีละตาราง
-- เพราะเลตเตอร์ออฟเครดิตกับทรัสต์รีซีทอ้างถึงกันไปมา เรียงลำดับลบยังไงก็ติด
-- CASCADE จัดลำดับให้เอง และข้ามตารางที่ยังไม่มีในฐานข้อมูลนี้
--
-- 58 ตารางนี้คือสัญญา ธุรกรรม เอกสารแนบ และผลพลอยได้ทางบัญชีทั้งหมด
-- ทะเบียนไม่อยู่ในรายการนี้ จึงไม่ถูกแตะ
DO $$
DECLARE
  v_t    TEXT;
  v_list TEXT := '';
BEGIN
  FOREACH v_t IN ARRAY ARRAY[
    'ap_cheque_requests', 'ar_ap_nettings', 'bank_statement_lines',
    'bank_statements', 'ca_collaterals', 'ca_conditions',
    'ca_documents', 'ca_guarantors', 'credit_agreements',
    'fa_transfers', 'facility_adjustments', 'floor_plans',
    'fp_ap_bills', 'fp_ar_bills', 'fp_chassis',
    'fp_documents', 'fx_forwards', 'fx_valuations',
    'fxf_documents', 'fxf_fair_values', 'fxf_fees',
    'installment_schedules', 'je_lines', 'journal_entries',
    'lc_documents', 'lease_asset_transfers', 'lease_documents',
    'lease_schedules', 'lease_versions', 'leases',
    'letter_guarantees', 'letters_of_credit', 'lg_documents',
    'lg_fees', 'loan_chassis', 'loan_documents',
    'loan_prepayments', 'loan_schedules', 'loans',
    'ma_collaterals', 'ma_conditions', 'ma_documents',
    'ma_guarantors', 'ma_subsidiaries', 'master_agreements',
    'netsuite_sync_log', 'od_bank_transactions', 'od_documents',
    'overdrafts', 'pn_documents', 'promissory_notes',
    'repayment_lines', 'repayments', 'tr_documents',
    'tr_imported_goods', 'trust_receipts', 'vehicle_movements',
    'vehicles'
  ] LOOP
    IF to_regclass('public.' || v_t) IS NOT NULL THEN
      v_list := v_list || CASE WHEN v_list = '' THEN '' ELSE ', ' END || quote_ident(v_t);
    END IF;
  END LOOP;

  IF v_list <> '' THEN
    EXECUTE 'TRUNCATE TABLE ' || v_list || ' CASCADE';
  END IF;
END $$;

